// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (material.answersFile ?? (reviewedKey ? 'reviewed-' + grade : grade + '-answers') + '.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2021, "4-5", [{"author":"Б. Иомдин","question":"В какой паре слова́ означают одно и то же?","choices":["<em>двор</em> — <em>дворец</em>","<em>свин — свинец</em>","<em>пёс — песец</em>","<em>молод</em> — <em>молодец</em>","<em>брат — братец</em>."],"key":"Д","review":["Когда слова равны по смыслу","Сравни значения вторых слов. Дворец — здание, свинец — металл, песец — зверь, а «молодец» может быть похвалой. Ни одно из этих слов не повторяет значения первого в своей паре.","Слово «братец» — ласковое название брата. Значение родства сохраняется, поэтому подходит вариант Д."]},{"author":"Б. Иомдин","question":"Какое слово образовано от названия дерева?","choices":["<em>калина</em>","<em>малина</em>","<em>осина</em>","<em>рябина</em>","<em>дубина.</em>"],"key":"Д","review":["Слово и название дерева","Сравни слова из ряда с названиями деревьев. Ищи слово, которое называет предмет и позволяет узнать дерево, из которого его могли сделать.","Дубина — толстая палка, а «дуб» — название дерева. К «дуб» прибавлен суффикс -ин-. Так устроено слово из варианта Д."]},{"author":"Б. Иомдин","question":"У какого из слов нет парного слова женского рода?","choices":["<em>любимец</em>","<em>любимчик</em>","<em>любимый</em>","<em>любитель</em>","у всех слов в (А)–(Г) есть женские варианты."],"key":"Б","review":["Мужские и женские слова","Подбери женское слово к каждому мужскому. «Любимец» — «любимица», «любимый» — «любимая», «любитель» — «любительница».","Девочку или женщину тоже можно назвать любимицей. У слова «любимчик» нет своего обычного парного слова вроде «любимчица». Выбираем Б."]},{"author":"О. Подлесская","question":"Какое из слов <strong>не</strong> образовано из двух слов?","choices":["<em>водопад</em>","<em>звездопад</em>","<em>камнепад</em>","<em>листопад</em>","<em>перепад</em>."],"key":"Д","review":["Что и откуда падает","В «водопаде», «звездопаде», «камнепаде» и «листопаде» первая часть подсказывает, что падает — вода, звёзды, камни или листья.","У слова «перепад» в начале приставка пере-, как в «перепадать». В его составе нет второй основы. Отличается вариант Д."]},{"author":"Л. Фёдорова","question":"Незнайка учится сочинять стихи. Он придумал стих, но не знает, как правильно записать некоторые слова. Знайка подсказал, что в четырёх строчках нужно вставить вместо двух пропусков две разные буквы, а в одной строчке <em>—</em> одну и ту же. В какой?","choices":["<em>Малы_ки играли в сне_ки</em>.","<em>Бума_ки сложили в ме_ки</em>.","<em>Рома_ки завяли в гор_ке</em>.","<em>Бука_ки топтались в кру_ке</em>.","<em>А мо_ки вились на лу_ке</em>."],"key":"В","review":["Две буквы в каждой строке","Проверь согласные перед гласной: малышек и снежок, бумажек и мешок, букашек и кружок, мошек и лужок. Получаются разные буквы в каждой паре.","«Ромашки» и «горшке» проверяются словами «ромашек» и «горшок». Оба раза пишется ш. Подходит строка В."]},{"author":"И. Рубанов","question":"Какое слово по смыслу лишнее?","choices":["<em>миллиграмм</em>","<em>миллилитр</em>","<em>миллиметр</em>","<em>миллион</em>","<em>миллисекунда</em>."],"key":"Г","review":["Слова на «милли-»","Начальная часть «милли-» в названиях мер означает одну тысячную. Миллиграмм — тысячная грамма, миллилитр — литра, миллиметр — метра, миллисекунда — секунды.","«Миллион» обозначает само число 1 000 000. Оно не называет долю единицы измерения и отличается по смыслу, вариант Г."]},{"author":"О. Подлесская","question":"Что может быть и у яйца, и у ореха?","choices":["желток","листок","скорлупа","ядро","ничего из (А)–(Г)."],"key":"В","review":["Яйцо и орех","Сравни внешнюю и внутреннюю части. Желток находится внутри яйца, а ядром в быту называют то, что достают из ореха.","И твёрдая оболочка яйца, и оболочка ореха называются скорлупой. Получилось одно привычное слово для обоих предметов, вариант В."]},{"author":"Е. Муравенко","question":"Найдите лишнее по смыслу.","choices":["<em>мебель</em>","<em>шкаф</em>","<em>стол</em>","<em>диван</em>","<em>кровать</em>."],"key":"А","review":["Предметы в комнате","Шкаф, стол, диван и кровать — отдельные предметы. Каждый можно нарисовать и описать, для чего его используют.","«Мебель» называет всю группу таких предметов. Это общее название среди частных, вариант А."]},{"author":"И. Рубанов","question":"Петя пришёл в гости в четверть седьмого, а Вася — без четверти семь. Кто из них пришёл позже и на сколько минут?","choices":["Петя пришёл позже на 15 минут","Петя и Вася пришли одновременно","Вася пришёл позже на 10 минут","Вася пришёл позже на 15 минут","Вася пришёл позже на 30 минут."],"key":"Д","review":["Два времени на часах","Одна четверть часа — 15 минут. Петя пришёл через 15 минут после шести, в 6:15, а Вася за 15 минут до семи, в 6:45.","Между 6:15 и 6:45 прошло 30 минут. Значит, позже пришёл Вася, вариант Д."]},{"author":"О. Подлесская","question":"Вставьте слово во фрагмент из «Денискиных рассказов» В. Драгунского: <em>Потом он</em> <em>вдруг стал откашливаться: «Кхм! Кхм!.. Кхме!.. ». Я сказал: «Ты что, Мишка,</em> <em>_____?».</em>","choices":["<em>разрыдался</em>","<em>расчихался</em>","<em>высморкался</em>","<em>прослезился</em>","<em>поперхнулся</em>."],"key":"Д","review":["Мишка откашливается","По звукам «кхм, кхм» и слову «откашливаться» видно, что Мишка пытается прочистить горло. Варианты о плаче, чихании и насморке описывают другие признаки.","Покашливание могло начаться, если что-то попало не туда при глотании. Для этого есть слово «поперхнулся», вариант Д."]},{"author":"Б. Иомдин","question":"Изучая тему «Многозначные слова», Стёпа выписывал из учебника русского языка слова, которые имеют и «неязыковые» значения. Но одно слово попало в его список по ошибке. Какое?","choices":["<em>род</em>","<em>число</em>","<em>лицо</em>","<em>падеж</em>","<em>время</em>."],"key":"Г","review":["Грамматика и другие значения","Каждое слово можно встретить в учебнике. Проверь, где оно встречается ещё. Есть род людей, число в математике, лицо человека и время суток.","«Паде́ж» называют грамматической формой слова. Массовую гибель животных называют «падёж» — с ё и другим ударным гласным. Лишнее слово — «падеж», вариант Г."]},{"author":"Е. Бикмаев","question":"От какого существительного в литературном языке не образуют прилагательное?","choices":["<em>сад</em>","<em>парк</em>","<em>сквер</em>","<em>бульвар</em>","<em>тротуар</em>."],"key":"В","review":["Прилагательные для города","Подставь знакомые сочетания — садовая дорожка, парковая аллея, бульварное кольцо, тротуарная плитка. Они помогают услышать четыре нужных прилагательных.","«Скверный» означает «плохой». Чтобы указать на сквер, обычно говорят «дорожки в сквере», «дорожки сквера». Для слова «сквер» в литературной норме нет такого прилагательного. Ответ В."]},{"author":"Н. Швайгер","question":"Продолжите пословицу: <em>Терпенье и труд всё _____</em>.","choices":["<em>перетруд</em>","<em>пир и труд</em>","<em>перетрут</em>","<em>переврут</em>","<em>притрут</em>."],"key":"В","review":["Конец знакомой пословицы","Терпеливая работа похожа на действие жерновов, которые постепенно перетирают даже твёрдые зёрна. В пословице нужно слово с таким смыслом.","Говорят «Терпенье и труд всё перетрут». «Перетрут» рифмуется с «труд», а вся пословица означает, что упорство помогает справиться с трудностями. Ответ В."]},{"author":"О. Подлесская","question":"<em>Стоять</em>, <em>вертеться, свернуться, упасть</em>. Найдите лишнее слово.","choices":["<em>калачиком</em>","<em>волчком</em>","<em>ничком</em>","<em>гуськом</em>","<em>особняком</em>."],"key":"Г","review":["Как можно двигаться и стоять","Восстанови знакомые сочетания. Можно стоять особняком, вертеться волчком, свернуться калачиком и упасть ничком.","«Гуськом» говорят о тех, кто идёт один за другим. «Идти» в списке глаголов нет. Остаётся вариант Г."]},{"author":"С. Дьяченко","question":"Какой важный в сельскохозяйственных работах день в некоторых русских говорах называют <em>докóпками</em>?","choices":["день, в который коптят рыбу","последний день уборки картофеля","день, когда начинают складывать сено в копны","последний день посадки капусты","день, когда подковывают лошадей."],"key":"Б","review":["Как назвали день в поле","В слове «докопки» слышится «докопать», то есть закончить копать. Среди дел из вариантов копают при уборке картошки.","Поэтому доко́пками называют последний день уборки картофеля, когда уже выкопано всё. Это вариант Б."]},{"author":"И. Рубанов","question":"Какое из этих выражений может означать то же, что <em>ни бе ни ме</em>?","choices":["<em>не ко двору</em>","<em>ни бум-бум</em>","<em>ни пуха ни пера</em>","<em>ни кола ни двора</em>","<em>ни на шаг</em>."],"key":"Б","review":["Похожие устойчивые выражения","«Ни бе ни ме» можно сказать про человека, который не может ничего сказать по теме или совсем в ней не разбирается. Ищи среди вариантов выражение о непонимании.","«Ни бум-бум» означает «ничего не знать, не понимать» — например, «в этом я ни бум-бум». В таком смысле выражения совпадают. Подходит Б."]},{"author":"Б. Иомдин","question":"Какое слово мы пропустили в первой строчке двустишия Ренаты Мухи?\n\n— Мне очень обидно, — сказала _______,\n— И я говорю это прямо в глаза.","choices":["<em>коза</em>","<em>гроза</em>","<em>слеза</em>","<em>медуза</em>","<em>оса</em>."],"key":"В","review":["Кто говорит в двустишии","К «глаза́» можно подобрать несколько рифм. Уточни по смыслу, что появляется у человека в глазах, когда ему очень обидно.","Это слеза́. Так выражение «прямо в глаза» связано с тем, где появляется говорящая героиня. Подходит вариант В."]},{"author":"Л. Фёдорова","question":"Вот отрывки из текстов А. С. Пушкина:\n1) Жил старик со своею старухой / У са́мого <strong>синего</strong> моря.\n2) Ты волнуешь <strong>сине</strong> море, / Всюду веешь на просторе.\n3) В <strong>синем</strong> небе звёзды блещут, / В <strong>синем</strong> море волны хлещут.\n4) Князь у <strong>синя</strong> моря ходит, / С <strong>синя</strong> моря глаз не сводит.\n5) Зазывает меня, Стеньку Разина, / Погулять по морю, по <strong>синему</strong>.\n6) Птичка в дальные страны, / В тёплый край, за <strong>сине</strong> море / Улетает до весны.\n\nВ каких примерах выделенные формы не используются в современном языке?","choices":["только в 4","только в 4 и 6","только в 2 и 4","в 2, 4 и 6","во всех примерах выделенные формы используются в современном языке."],"key":"Г","review":["Старая форма у Пушкина","Сравни выделенные формы с современными. «Синего моря», «в синем небе», «в синем море» и «по синему морю» можно сказать и сегодня. Это примеры 1, 3 и 5.","Сегодня говорят «волнуешь синее море» и «за синее море», а также «у синего моря» и «с синего моря». Старые формы «сине» и «синя» были в примерах 2, 4 и 6. Это вариант Г."]},{"author":"О. Подлесская","question":"Польский язык, как и русский, относится к славянской группе языков. Какая ягода по-польски называется poziomka?","choices":["малина","крыжовник","вишня","земляника","облепиха."],"key":"Г","review":["Название ягоды по-польски","Польское «poziomka» происходит от «po ziemi», то есть «по земле». Так могли назвать ягоду, которая растёт низко, у самой земли.","В русском названии «земляника» слышится та же связь со словом «земля». Эта ягода подходит, вариант Г."]},{"author":"С. Переверзева","question":"Тётя Катя предложила маленькому Ване пойти с ней на речку купаться, на что тот ответил: «Я уже умею!» Как называлась эта речка?","choices":["<em>Шухорма</em>","<em>Уча</em>","<em>Яуза</em>","<em>Гвоздянка</em>","<em>Ока</em>."],"key":"Б","review":["Ваня и название речки","Ребёнок отвечает так, будто решил, что его хотят научить купаться. Название речки в фразе тёти должно напомнить ему знакомый глагол.","Если речка называется Уча, можно сказать «пойдём на Учу купаться». «Учу купаться» звучит как обещание научить. Ваня отвечает, что уже умеет. Это вариант Б."]},{"author":"Е. Муравенко","question":"Какое название животного устроено не так, как остальные?","choices":["<em>суслик</em>","<em>ослик</em>","<em>козлик</em>","<em>зайчик</em>","<em>пёсик</em>."],"key":"А","review":["Состав названий животных","Поставь рядом обычное и ласковое название — осёл и ослик, козёл и козлик, заяц и зайчик, пёс и пёсик. Все четыре образованы от слова для того же животного.","В современном слове «суслик» целиком выделяется корень «суслик-». Это самостоятельное название, которое только похоже на уменьшительное. Подходит вариант А."]},{"author":"Л. Фёдорова","question":"Марина задумала слово, означающее качество, и стала подбирать слова, к которым оно подходит: <em>камешек</em>, <em>год</em>, <em>стол</em>, <em>лицо</em>… Какое ещё слово можно добавить в этот ряд?","choices":["<em>трава</em>","<em>век</em>","<em>отличница</em>","<em>заяц</em>","<em>грабли</em>."],"key":"В","review":["Прилагательное для списка","Найди общее слово — стол и камешек могут быть круглыми, как и лицо. «Круглый год» означает «в течение всего года».","«Круглая отличница» получает отличные оценки по всем предметам. У неё то же прилагательное со значением полноты. Подходит вариант В."]},{"author":"П. Аркадьев","question":"<em>Глаза</em>, <em>зуб</em>, <em>нос</em>, <em>рука</em>. Вспомните однотипные устойчивые выражения с этими словами и расставьте предлоги в правильном порядке.","choices":["<em>в</em>, <em>к</em>, <em>на</em>, <em>об</em>","<em>в</em>, <em>на</em>, <em>к</em>, <em>об</em>","<em>на</em>, <em>об</em>, <em>к</em>, <em>в</em>","<em>об</em>, <em>на</em>, <em>в</em>, <em>к</em>","<em>к</em>, <em>в</em>, <em>на</em>, <em>об</em>."],"key":"Б","review":["Предлоги между повторениями","Ищи обороты, в которых название части тела повторяется. В «глаза в глаза» употребляется «в», а когда кто-то дрожит, у него «зуб на зуб не попадает».","«Нос к носу» и «рука об руку» дают «к» и «об». Порядок «в, на, к, об» — вариант Б."]},{"author":"С. Переверзева","question":"Маленький Лёва считает, что, когда чего-то ждёшь, ОНО надувается. ОНО — это _____.","choices":["время","спокойствие","безделье","волнение","терпение."],"key":"Д","review":["Ожидание Лёвы","В устойчивом выражении «терпение лопнуло» человек больше не готов ждать или мириться с происходящим.","Лёва понял выражение буквально. Раз терпение может лопнуть, оно, по его мысли, во время ожидания надувается, как шарик. Это вариант Д."]},{"author":"Е. Пискунова","question":"В книге Владислава Крапивина «Сказки Севки Глущенко» главный герой учится писать буквы. Одна из них вызывает определённые трудности. Мальчик размышляет: «... сложная буква. Будто даже не одна, а две. Это слились _____».","choices":["И и Ш","П и Г","Н и О","Я и Р","Ъ и Г."],"key":"В","review":["Буква в прописи","Попробуй соединить части двух букв. Возьми у Н левую вертикальную черту и поперечную перекладину.","Если вместо правой черты Н приставить к перекладине овал буквы О, получится Ю. Именно так рассуждает Севка, когда учится её писать. Подходит пара «Н и О», вариант В."]},{"author":"И. Рубанов","question":"Андрей вынужден пойти к врачу. Боря должен пойти к врачу. Вере надо пойти к врачу. Грише необходимо пойти к врачу. Дима обязан пойти к врачу. Кто из них точно не хочет идти к врачу?","choices":["Андрей","Боря","Вера","Гриша","Дима."],"key":"А","review":["Почему идут к врачу","«Должен», «надо», «необходимо» и «обязан» сообщают о необходимости визита. При этом человек вполне может сам хотеть обратиться к врачу.","«Вынужден» подчёркивает давление обстоятельств и звучит как действие против желания. Этот оттенок есть в предложении об Андрее, вариант А."]},{"author":"О. Подлесская","question":"В детском журнале «Чиж» 1930 года напечатали такую загадку. Разгадайте её и вы!\n\nЗагадка у меня к вам есть,\nЗагадка непростая:\nКакую букву можно есть,\nКогда она пустая?","choices":["З","И","К","О","Р."],"key":"В","review":["Загадка о букве","В загадке важно не начертание буквы, а её название. К произносится как «ка». Соедини это название со словом «пуста».","Сочетание «ка пуста» складывается в «капуста». Овощ можно съесть, так что ответ — буква К, вариант В."]},{"author":"Е. Муравенко","question":"Даны слова <em>лист</em>, <em>сталь</em>, <em>стиль</em> и <em>стол</em>. Какие два из них содержат одинаковый набор согласных звуков?","choices":["<em>лист</em> и <em>сталь</em>","<em>лист</em> и <em>стиль</em>","<em>лист</em> и <em>стол</em>","<em>сталь</em> и <em>стиль</em>","<em>сталь</em> и <em>стол</em>."],"key":"А","review":["Согласные в четырёх словах","Произнеси «лист» и «сталь». В обоих словах слышатся твёрдые [с] и [т] и мягкий [л’], только в разном порядке.","В слове «стиль» звук [т’] мягкий, а в слове «стол» звук [л] твёрдый. Поэтому одинаковый набор только у слов «лист» и «сталь», вариант А."]},{"author":"И. Скоморохова","question":"За круглым столом сидят пятеро: Зина, Лев, Толя, Влад и Кира. Если первую букву имени каждого из них поменять на первую букву имени соседа справа, то из их имён получится пять слов. В каком порядке все сидели за столом?","choices":["Зина, Лев, Толя, Влад, Кира","Кира, Лев, Зина, Влад, Толя","Влад, Кира, Лев, Зина, Толя","Лев, Зина, Влад, Толя, Кира","Толя, Зина, Влад, Лев, Кира."],"key":"В","review":["Имена за круглым столом","Проверяй, превращается ли каждое имя в слово, когда его первая буква взята у следующего имени справа. Например, Влад с буквой К от Киры даёт «клад».","Проверь цепочку по кругу. Влад → клад, Кира → лира, Лев → зев, Зина → тина, Толя → воля благодаря букве В от Влада. Такой порядок указан в варианте В."]},{"author":"С. Переверзева","question":"Даны предлоги: <em>во</em>, <em>ко</em>, <em>со</em>, <em>до</em>.\nКакой из них устроен не так, как остальные?","choices":["<em>во</em>","<em>ко</em>","<em>со</em>","<em>до</em>","все эти предлоги устроены одинаково."],"key":"Г","review":["Длинные и короткие предлоги","Сравни «в лесу — во сне», «к дому — ко мне», «с другом — со мной». В каждой паре есть короткая форма предлога и форма на о.","«До» всегда пишется с о. Короткого предлога «д» в русском языке нет. Поэтому «до» отличается, вариант Г."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
